30	
31	    @Bean
32	    public PasswordEncoder passwordEncoder() {
33	        return new BCryptPasswordEncoder();
34	    }
35	
36	    @Bean
37	    public DaoAuthenticationProvider authenticationProvider() {
38	        DaoAuthenticationProvider provider = new DaoAuthenticationProvider();
39	        provider.setUserDetailsService(userDetailsService);
40	        provider.setPasswordEncoder(passwordEncoder());
41	        return provider;
42	    }
43	
44	    @Bean
45	    public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
46	        return config.getAuthenticationManager();
47	    }
48	
49	    @Bean
50	    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
51	        http
52	                .csrf(csrf -> csrf.disable())
53	                .cors(Customizer.withDefaults())
54	                .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
55	                .authorizeHttpRequests(auth -> auth
56	                        .requestMatchers("/api/v1/auth/**", "/actuator/health", "/docs/**", "/api-docs/**", "/swagger-ui/**", "/ws/**").permitAll()
57	                        .anyRequest().authenticated()
58	                )
59	                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);
60	        return http.build();
61	    }
62	}

